import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353;

    static long fastExponentiation(long base, long exponent) {
        long result = 1L;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exponent >>= 1;
        }
        return result;
    }

    static long modInverse(long x) {
        return fastExponentiation(x, MOD - 2);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokenizer = new StringTokenizer(br.readLine());
        long n = Long.parseLong(tokenizer.nextToken());
        long m = Long.parseLong(tokenizer.nextToken());
        long l = Long.parseLong(tokenizer.nextToken());
        long r = Long.parseLong(tokenizer.nextToken());

        PrintWriter pw = new PrintWriter(System.out);
        if (l == r) {
            pw.println(1);
            pw.flush();
            return;
        }

        long oddCount = ((r + 1) / 2) - (l / 2);
        long evenCount = (r / 2) - ((l - 1) / 2);
        long totalCells = n * m;

        long answer;
        if (totalCells % 2 == 1) {
            answer = fastExponentiation(oddCount + evenCount, totalCells);
        } else {
            long sum = (fastExponentiation(oddCount + evenCount, totalCells) + fastExponentiation(oddCount - evenCount, totalCells)) % MOD;
            answer = (sum * modInverse(2)) % MOD;
        }
        pw.println(answer);
        pw.flush();
    }
}
